use super::*;
/// The direct ambient-form reference generated by a bounded membrane fixture. It deliberately
/// expands bilinear entries and therefore remains test-only. Form order inside each restriction is
/// `(reflected families, action families, receiver overlaps, receiver norms)`.
#[cfg(test)]
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct MembraneObservableIntegralFrame {
    pub schema: String,
    pub frame: ObservableIntegralFormFrame,
    pub primitive_restrictions: Vec<Vec<(u32, BigUint)>>,
    pub transition_restriction_factors: Vec<IntegralRestrictionFrameFactor>,
    pub family_population: u32,
    pub receiver_population: u32,
    pub generator_population: u32,
    pub present_forms_per_restriction: u32,
}

#[cfg(test)]
impl MembraneObservableIntegralFrame {
    #[allow(clippy::too_many_arguments)]
    pub fn found(
        factor_capacity: &[u64],
        family_orientation: &[i8],
        factor_receiver_classes: &[u32],
        receiver_class_counts: &[u32],
        restrictions: Vec<Vec<(u32, BigUint)>>,
        generators: Vec<Vec<u32>>,
    ) -> Result<Self, ObservableMomentCompressionError> {
        let factors = factor_capacity.len();
        let families = if factors == 0 {
            0
        } else {
            family_orientation.len() / factors
        };
        let receivers = receiver_class_counts.len();
        if factors == 0
            || families == 0
            || receivers == 0
            || restrictions.is_empty()
            || generators.is_empty()
            || factors > u32::MAX as usize
            || family_orientation.len() != families.saturating_mul(factors)
            || factor_receiver_classes.len() != factors.saturating_mul(receivers)
            || factor_capacity.iter().any(|capacity| *capacity == 0)
            || family_orientation
                .iter()
                .any(|orientation| !matches!(*orientation, -1 | 0 | 1))
            || factor_receiver_classes
                .chunks_exact(receivers)
                .any(|classes| {
                    classes
                        .iter()
                        .zip(receiver_class_counts)
                        .any(|(class, count)| *count == 0 || *class >= *count)
                })
            || generators.iter().any(|generator| {
                generator.len() != factors
                    || generator.iter().any(|target| *target as usize >= factors)
            })
        {
            return Err(ObservableMomentCompressionError::Shape);
        }

        let mut primitive_restrictions = Vec::<Vec<(u32, BigUint)>>::new();
        let mut restriction_addresses = BTreeMap::<Vec<(u32, BigUint)>, u32>::new();
        let mut transition_restriction_factors = Vec::with_capacity(restrictions.len());
        for mut restriction in restrictions {
            restriction.sort_by_key(|(factor, _)| *factor);
            if restriction.is_empty()
                || restriction.windows(2).any(|pair| pair[0].0 >= pair[1].0)
                || restriction.iter().any(|(factor, coefficient)| {
                    *factor as usize >= factors || coefficient.is_zero()
                })
            {
                return Err(ObservableMomentCompressionError::Shape);
            }
            let divisor = restriction
                .iter()
                .map(|(_, coefficient)| coefficient.clone())
                .reduce(exact_biguint_gcd)
                .ok_or(ObservableMomentCompressionError::Shape)?;
            let primitive = restriction
                .into_iter()
                .map(|(factor, coefficient)| (factor, coefficient / &divisor))
                .collect::<Vec<_>>();
            let restriction_class = if let Some(address) = restriction_addresses.get(&primitive) {
                *address
            } else {
                let address = u32::try_from(primitive_restrictions.len())
                    .map_err(|_| ObservableMomentCompressionError::Shape)?;
                restriction_addresses.insert(primitive.clone(), address);
                primitive_restrictions.push(primitive);
                address
            };
            transition_restriction_factors.push(IntegralRestrictionFrameFactor {
                restriction_class,
                quadratic_scale: &divisor * &divisor,
            });
        }

        let factor_population = factors as u32;
        let mut present_forms = Vec::new();
        for restriction in &primitive_restrictions {
            let mut restricted = vec![BigInt::ZERO; factors];
            for (factor, coefficient) in restriction {
                restricted[*factor as usize] = BigInt::from(coefficient.clone());
            }
            for family in 0..families {
                let mut entries = BTreeMap::<(u32, u32), BigInt>::new();
                for factor in 0..factors {
                    let incidence = &restricted[factor];
                    let orientation = family_orientation[family * factors + factor];
                    if incidence.is_zero() || orientation == 0 {
                        continue;
                    }
                    let coefficient = BigInt::from(factor_capacity[factor])
                        * BigInt::from(orientation)
                        * incidence
                        * incidence
                        * BigInt::from(generators.len());
                    *entries.entry((factor as u32, factor as u32)).or_default() += coefficient;
                }
                present_forms.push(SparseIntegralBilinearForm::new(factor_population, entries)?);
            }
            for family in 0..families {
                let mut entries = BTreeMap::<(u32, u32), BigInt>::new();
                for source in 0..factors {
                    let source_incidence = &restricted[source];
                    if source_incidence.is_zero() {
                        continue;
                    }
                    let source_orientation = family_orientation[family * factors + source];
                    if source_orientation != 0 {
                        let diagonal = BigInt::from(factor_capacity[source])
                            * BigInt::from(source_orientation)
                            * source_incidence
                            * source_incidence
                            * BigInt::from(generators.len());
                        *entries.entry((source as u32, source as u32)).or_default() -= diagonal;
                    }
                    for generator in &generators {
                        let target = generator[source] as usize;
                        let target_incidence = &restricted[target];
                        let target_orientation = family_orientation[family * factors + target];
                        if target_incidence.is_zero() || target_orientation == 0 {
                            continue;
                        }
                        let cross = BigInt::from(factor_capacity[target])
                            * BigInt::from(target_orientation)
                            * target_incidence
                            * source_incidence;
                        *entries.entry((target as u32, source as u32)).or_default() += cross;
                    }
                }
                present_forms.push(SparseIntegralBilinearForm::new(factor_population, entries)?);
            }
            for receiver in 0..receivers {
                let mut overlap = BTreeMap::<(u32, u32), BigInt>::new();
                let mut norm = BTreeMap::<(u32, u32), BigInt>::new();
                for class in 0..receiver_class_counts[receiver] {
                    let source = (0..factors)
                        .filter(|factor| {
                            factor_receiver_classes[*factor * receivers + receiver] == class
                                && !restricted[*factor].is_zero()
                        })
                        .map(|factor| (factor as u32, restricted[factor].clone()))
                        .collect::<Vec<_>>();
                    if source.is_empty() {
                        continue;
                    }
                    for generator in &generators {
                        let target_preimage = (0..factors)
                            .filter(|factor| {
                                factor_receiver_classes
                                    [generator[*factor] as usize * receivers + receiver]
                                    == class
                                    && !restricted[*factor].is_zero()
                            })
                            .map(|factor| (factor as u32, restricted[factor].clone()))
                            .collect::<Vec<_>>();
                        accumulate_sparse_outer(&mut overlap, &source, &target_preimage, 1);
                        accumulate_sparse_outer(&mut overlap, &source, &source, -1);
                        let difference = sparse_vector_difference(&target_preimage, &source);
                        accumulate_sparse_outer(&mut norm, &difference, &difference, 1);
                    }
                }
                present_forms.push(SparseIntegralBilinearForm::new(factor_population, overlap)?);
                present_forms.push(SparseIntegralBilinearForm::new(factor_population, norm)?);
            }
        }
        let present_forms_per_restriction = families
            .checked_mul(2)
            .and_then(|count| count.checked_add(receivers.checked_mul(2)?))
            .ok_or(ObservableMomentCompressionError::Shape)?;
        if present_forms.len()
            != primitive_restrictions
                .len()
                .saturating_mul(present_forms_per_restriction)
        {
            return Err(ObservableMomentCompressionError::Factorization);
        }
        let frame = ObservableIntegralFormFrame::found(present_forms, generators.clone())?;
        Ok(Self {
            schema: "holonic-engine.membrane-observable-integral-frame.v1".to_owned(),
            frame,
            primitive_restrictions,
            transition_restriction_factors,
            family_population: families as u32,
            receiver_population: receivers as u32,
            generator_population: generators.len() as u32,
            present_forms_per_restriction: present_forms_per_restriction as u32,
        })
    }
}

pub(crate) fn exact_biguint_gcd(mut left: BigUint, mut right: BigUint) -> BigUint {
    while !right.is_zero() {
        let remainder = left % &right;
        left = right;
        right = remainder;
    }
    left
}

#[cfg(test)]
fn accumulate_sparse_outer(
    into: &mut BTreeMap<(u32, u32), BigInt>,
    left: &[(u32, BigInt)],
    right: &[(u32, BigInt)],
    sign: i8,
) {
    for (row, left_coefficient) in left {
        for (column, right_coefficient) in right {
            *into.entry((*row, *column)).or_default() +=
                BigInt::from(sign) * left_coefficient * right_coefficient;
        }
    }
}

#[cfg(test)]
fn sparse_vector_difference(left: &[(u32, BigInt)], right: &[(u32, BigInt)]) -> Vec<(u32, BigInt)> {
    let mut difference = BTreeMap::<u32, BigInt>::new();
    for (factor, coefficient) in left {
        *difference.entry(*factor).or_default() += coefficient;
    }
    for (factor, coefficient) in right {
        *difference.entry(*factor).or_default() -= coefficient;
    }
    difference.retain(|_, coefficient| !coefficient.is_zero());
    difference.into_iter().collect()
}

/// One partial generator square. Source and native termini are explicit members of the incidence,
/// not missing data and never invented self-loops.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct PartialGeneratorSquare {
    pub generator: InputId,
    pub source: Vec<SourceTransport>,
    pub terminating_sources: BTreeSet<ItemId>,
    pub native: Vec<NativeTransport>,
    pub terminating_natives: BTreeSet<NativeStateId>,
}

/// Exact receiver-history compression for a finite ecology with an open exterior. A native class
/// either transports wholly through a generator or terminates wholly at that port; a mixed class
/// is a returned obstruction to descent.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct PartialReceiverHistoryCompression {
    pub schema: String,
    pub source_population: Vec<ItemId>,
    pub native_population: Vec<NativeStateId>,
    pub quotient: Vec<QuotientAssignment>,
    pub receiver_factors: Vec<ReceiverFactor>,
    pub generators: Vec<PartialGeneratorSquare>,
    pub reconstruction_fibres: Vec<ReconstructionFibre>,
    pub first_separators: Vec<CollapsedPair>,
    pub construction_work: ReceiverHistoryWork,
}

#[derive(Clone, Debug, PartialEq, Eq, Error)]
pub enum ReceiverHistoryRefusal {
    #[error("receiver-history wire refused: {0}")]
    Wire(String),
    #[error("the source population is empty or repeats an identity")]
    SourcePopulation,
    #[error("the native population is empty or repeats an identity")]
    NativePopulation,
    #[error("source item {0:?} occurs in no conduct fibre")]
    SourceOutsideQuotient(ItemId),
    #[error("source item {0:?} occurs in more than one conduct fibre")]
    SourceOccursInPluralFibres(ItemId),
    #[error("conduct fibre {0:?} is empty")]
    EmptyFibre(NativeStateId),
    #[error("receiver {receiver:?} does not factor on native state {native:?}")]
    ReceiverDoesNotFactor {
        native: NativeStateId,
        receiver: ReceiverId,
    },
    #[error(
        "generator {generator:?} terminates at source item {source_item:?}; M3 requires a total typed transport"
    )]
    SourceTransportTerminates {
        generator: InputId,
        source_item: ItemId,
    },
    #[error(
        "generator {generator:?} leaves the declared source population from {source_item:?} to {target:?}"
    )]
    SourceTransportLeavesPopulation {
        generator: InputId,
        source_item: ItemId,
        target: ItemId,
    },
    #[error("generator {generator:?} does not induce one native successor on fibre {native:?}")]
    GeneratorDoesNotDescend {
        generator: InputId,
        native: NativeStateId,
    },
    #[error("generator square {generator:?} fails at source item {source_item:?}")]
    GeneratorSquareDoesNotCommute {
        generator: InputId,
        source_item: ItemId,
    },
    #[error("source item {0:?} is not in the quotient map")]
    UnknownSource(ItemId),
    #[error("native state {0:?} is not in the quotient")]
    UnknownNative(NativeStateId),
    #[error("generator {0:?} is not in the native action")]
    UnknownGenerator(InputId),
    #[error("receiver {receiver:?} is not declared on native state {native:?}")]
    UnknownReceiverFactor {
        native: NativeStateId,
        receiver: ReceiverId,
    },
    #[error("receiver factors do not form one complete declared family on native state {0:?}")]
    ReceiverFactorPopulation(NativeStateId),
    #[error("generator {0:?} is repeated")]
    DuplicateGenerator(InputId),
    #[error("the exact construction-work receipt disagrees with the validated relation population")]
    ConstructionWork,
    #[error("a shortest separator is malformed or leaves the declared passage")]
    Separator,
}

impl ReceiverHistoryCompression {
    /// Reopen a serialized compression and rederive every structural law it claims.
    pub fn read(bytes: &[u8]) -> Result<Self, ReceiverHistoryRefusal> {
        let compression: Self = serde_json::from_slice(bytes)
            .map_err(|error| ReceiverHistoryRefusal::Wire(error.to_string()))?;
        compression.validate()?;
        Ok(compression)
    }

    /// Validate the complete finite passage without consulting the source system which founded it.
    ///
    /// This is deliberately stronger than a schema check.  It reopens the quotient partition,
    /// complete reconstruction fibres, receiver-factor family, total source/native generators,
    /// every local naturality square, shortest-separator addresses and exact structural-work
    /// population.  The observations themselves remain opaque exact faces.
    pub fn validate(&self) -> Result<(), ReceiverHistoryRefusal> {
        if self.schema != "holonic-engine.receiver-history-compression.v1" {
            return Err(ReceiverHistoryRefusal::Wire(format!(
                "unknown schema {}",
                self.schema
            )));
        }
        let mut source_set = BTreeSet::new();
        for source in &self.source_population {
            source_set.insert(*source);
        }
        if source_set.is_empty() || source_set.len() != self.source_population.len() {
            return Err(ReceiverHistoryRefusal::SourcePopulation);
        }
        let mut native_set = BTreeSet::new();
        for native in &self.native_population {
            native_set.insert(*native);
        }
        if native_set.is_empty() || native_set.len() != self.native_population.len() {
            return Err(ReceiverHistoryRefusal::NativePopulation);
        }

        let mut encoded = BTreeMap::<ItemId, NativeStateId>::new();
        for assignment in &self.quotient {
            if !source_set.contains(&assignment.source)
                || !native_set.contains(&assignment.native)
                || encoded
                    .insert(assignment.source, assignment.native)
                    .is_some()
            {
                return Err(ReceiverHistoryRefusal::SourceOccursInPluralFibres(
                    assignment.source,
                ));
            }
        }
        for source in &source_set {
            if !encoded.contains_key(source) {
                return Err(ReceiverHistoryRefusal::SourceOutsideQuotient(*source));
            }
        }

        let mut fibre_by_native = BTreeMap::<NativeStateId, &BTreeSet<ItemId>>::new();
        let mut fibre_union = BTreeSet::new();
        for fibre in &self.reconstruction_fibres {
            if !native_set.contains(&fibre.native)
                || fibre.sources.is_empty()
                || fibre_by_native
                    .insert(fibre.native, &fibre.sources)
                    .is_some()
            {
                return Err(ReceiverHistoryRefusal::EmptyFibre(fibre.native));
            }
            for source in &fibre.sources {
                if !source_set.contains(source)
                    || !fibre_union.insert(*source)
                    || encoded.get(source) != Some(&fibre.native)
                {
                    return Err(ReceiverHistoryRefusal::SourceOccursInPluralFibres(*source));
                }
            }
        }
        if fibre_by_native.len() != native_set.len()
            || native_set
                .iter()
                .any(|native| !fibre_by_native.contains_key(native))
            || fibre_union != source_set
        {
            return Err(ReceiverHistoryRefusal::NativePopulation);
        }

        let mut receiver_set = BTreeSet::new();
        for factor in &self.receiver_factors {
            receiver_set.insert(factor.receiver);
        }
        let mut factor_keys = BTreeSet::new();
        let mut receivers_by_native = BTreeMap::<NativeStateId, BTreeSet<ReceiverId>>::new();
        for factor in &self.receiver_factors {
            if !native_set.contains(&factor.native)
                || !factor_keys.insert((factor.native, factor.receiver))
            {
                return Err(ReceiverHistoryRefusal::UnknownReceiverFactor {
                    native: factor.native,
                    receiver: factor.receiver,
                });
            }
            receivers_by_native
                .entry(factor.native)
                .or_default()
                .insert(factor.receiver);
        }
        for native in &native_set {
            if receivers_by_native.get(native) != Some(&receiver_set) {
                return Err(ReceiverHistoryRefusal::ReceiverFactorPopulation(*native));
            }
        }

        let mut generator_ids = BTreeSet::new();
        for square in &self.generators {
            if !generator_ids.insert(square.generator) {
                return Err(ReceiverHistoryRefusal::DuplicateGenerator(square.generator));
            }
            let mut source_map = BTreeMap::new();
            for edge in &square.source {
                if !source_set.contains(&edge.from)
                    || !source_set.contains(&edge.to)
                    || source_map.insert(edge.from, edge.to).is_some()
                {
                    return Err(ReceiverHistoryRefusal::SourceTransportLeavesPopulation {
                        generator: square.generator,
                        source_item: edge.from,
                        target: edge.to,
                    });
                }
            }
            if source_map.len() != source_set.len()
                || source_set
                    .iter()
                    .any(|source| !source_map.contains_key(source))
            {
                let missing = source_set
                    .iter()
                    .find(|source| !source_map.contains_key(source))
                    .copied()
                    .unwrap_or(ItemId(0));
                return Err(ReceiverHistoryRefusal::SourceTransportTerminates {
                    generator: square.generator,
                    source_item: missing,
                });
            }

            let mut native_map = BTreeMap::new();
            for edge in &square.native {
                if !native_set.contains(&edge.from)
                    || !native_set.contains(&edge.to)
                    || native_map.insert(edge.from, edge.to).is_some()
                {
                    return Err(ReceiverHistoryRefusal::GeneratorDoesNotDescend {
                        generator: square.generator,
                        native: edge.from,
                    });
                }
            }
            if native_map.len() != native_set.len()
                || native_set
                    .iter()
                    .any(|native| !native_map.contains_key(native))
            {
                let missing = native_set
                    .iter()
                    .find(|native| !native_map.contains_key(native))
                    .copied()
                    .unwrap_or(NativeStateId(0));
                return Err(ReceiverHistoryRefusal::GeneratorDoesNotDescend {
                    generator: square.generator,
                    native: missing,
                });
            }
            for (source, target) in source_map {
                if encoded[&target] != native_map[&encoded[&source]] {
                    return Err(ReceiverHistoryRefusal::GeneratorSquareDoesNotCommute {
                        generator: square.generator,
                        source_item: source,
                    });
                }
            }
        }

        for separator in &self.first_separators {
            if separator.left == separator.right
                || !source_set.contains(&separator.left)
                || !source_set.contains(&separator.right)
                || separator.distinguishing_word.is_empty()
                || separator
                    .distinguishing_word
                    .iter()
                    .any(|generator| !generator_ids.contains(generator))
                || separator.witness.is_some_and(|(receiver, left, right)| {
                    !receiver_set.contains(&receiver) || left == right
                })
                || (!separator.separated_by_terminus && separator.witness.is_none())
            {
                return Err(ReceiverHistoryRefusal::Separator);
            }
        }

        let source_count = self.source_population.len() as u64;
        let native_count = self.native_population.len() as u64;
        let generator_count = self.generators.len() as u64;
        let receiver_count = receiver_set.len() as u64;
        let expected = ReceiverHistoryWork {
            quotient_assignments: source_count,
            receiver_factor_reads: source_count * receiver_count,
            source_transport_reads: source_count * generator_count,
            native_transport_entries: native_count * generator_count,
            generator_square_checks: source_count * generator_count,
        };
        if self.construction_work != expected {
            return Err(ReceiverHistoryRefusal::ConstructionWork);
        }
        Ok(())
    }

    /// Found the native action from an already-computed stable receiver/history partition.
    pub fn found(
        system: &dyn ObservedSystem,
        exact: &ReceiverExactCompression,
    ) -> Result<Self, ReceiverHistoryRefusal> {
        let mut source_population = system.items();
        source_population.sort_unstable();
        source_population.dedup();
        let source_set = source_population.iter().copied().collect::<BTreeSet<_>>();

        let mut quotient = Vec::with_capacity(source_population.len());
        let mut reconstruction_fibres = Vec::with_capacity(exact.conduct.blocks.len());
        let mut encoded = BTreeMap::<ItemId, NativeStateId>::new();
        for (at, sources) in exact.conduct.blocks.iter().enumerate() {
            let native = NativeStateId(at as u64);
            if sources.is_empty() {
                return Err(ReceiverHistoryRefusal::EmptyFibre(native));
            }
            for source in sources {
                if encoded.insert(*source, native).is_some() {
                    return Err(ReceiverHistoryRefusal::SourceOccursInPluralFibres(*source));
                }
                quotient.push(QuotientAssignment {
                    source: *source,
                    native,
                });
            }
            reconstruction_fibres.push(ReconstructionFibre {
                native,
                sources: sources.clone(),
            });
        }
        for source in &source_population {
            if !encoded.contains_key(source) {
                return Err(ReceiverHistoryRefusal::SourceOutsideQuotient(*source));
            }
        }
        quotient.sort_by_key(|assignment| assignment.source);
        let native_population = reconstruction_fibres
            .iter()
            .map(|fibre| fibre.native)
            .collect::<Vec<_>>();

        let receivers = system.receivers();
        let mut receiver_factors = Vec::with_capacity(native_population.len() * receivers.len());
        let mut receiver_factor_reads = 0u64;
        for fibre in &reconstruction_fibres {
            for receiver in &receivers {
                let mut readings = fibre.sources.iter().map(|source| {
                    receiver_factor_reads += 1;
                    system.observation(*source, *receiver)
                });
                let first = readings
                    .next()
                    .ok_or(ReceiverHistoryRefusal::EmptyFibre(fibre.native))?;
                if readings.any(|reading| reading != first) {
                    return Err(ReceiverHistoryRefusal::ReceiverDoesNotFactor {
                        native: fibre.native,
                        receiver: *receiver,
                    });
                }
                receiver_factors.push(ReceiverFactor {
                    native: fibre.native,
                    receiver: *receiver,
                    observation: first,
                });
            }
        }

        let mut generators = Vec::with_capacity(system.inputs().len());
        let mut source_transport_reads = 0u64;
        let mut native_transport_entries = 0u64;
        let mut generator_square_checks = 0u64;
        for generator in system.inputs() {
            let mut source = Vec::with_capacity(source_population.len());
            for from in &source_population {
                source_transport_reads += 1;
                let to = system.successor(*from, generator).ok_or(
                    ReceiverHistoryRefusal::SourceTransportTerminates {
                        generator,
                        source_item: *from,
                    },
                )?;
                if !source_set.contains(&to) {
                    return Err(ReceiverHistoryRefusal::SourceTransportLeavesPopulation {
                        generator,
                        source_item: *from,
                        target: to,
                    });
                }
                source.push(SourceTransport { from: *from, to });
            }

            let source_map = source
                .iter()
                .map(|edge| (edge.from, edge.to))
                .collect::<BTreeMap<_, _>>();
            let mut native = Vec::with_capacity(native_population.len());
            for fibre in &reconstruction_fibres {
                let targets = fibre
                    .sources
                    .iter()
                    .filter_map(|member| source_map.get(member))
                    .filter_map(|target| encoded.get(target))
                    .copied()
                    .collect::<BTreeSet<_>>();
                if targets.len() != 1 {
                    return Err(ReceiverHistoryRefusal::GeneratorDoesNotDescend {
                        generator,
                        native: fibre.native,
                    });
                }
                native_transport_entries += 1;
                native.push(NativeTransport {
                    from: fibre.native,
                    to: *targets.iter().next().expect("one target was established"),
                });
            }
            let native_map = native
                .iter()
                .map(|edge| (edge.from, edge.to))
                .collect::<BTreeMap<_, _>>();
            for edge in &source {
                generator_square_checks += 1;
                let left = encoded[&edge.to];
                let right = native_map[&encoded[&edge.from]];
                if left != right {
                    return Err(ReceiverHistoryRefusal::GeneratorSquareDoesNotCommute {
                        generator,
                        source_item: edge.from,
                    });
                }
            }
            generators.push(GeneratorSquare {
                generator,
                source,
                native,
            });
        }

        let compression = Self {
            schema: "holonic-engine.receiver-history-compression.v1".to_owned(),
            source_population,
            native_population,
            quotient,
            receiver_factors,
            generators,
            reconstruction_fibres,
            first_separators: exact.collapsed.clone(),
            construction_work: ReceiverHistoryWork {
                quotient_assignments: encoded.len() as u64,
                receiver_factor_reads,
                source_transport_reads,
                native_transport_entries,
                generator_square_checks,
            },
        };
        compression.validate()?;
        Ok(compression)
    }

    pub fn encode(&self, source: ItemId) -> Result<NativeStateId, ReceiverHistoryRefusal> {
        self.quotient
            .binary_search_by_key(&source, |assignment| assignment.source)
            .ok()
            .and_then(|at| self.quotient.get(at))
            .map(|assignment| assignment.native)
            .ok_or(ReceiverHistoryRefusal::UnknownSource(source))
    }

    /// Decode exactly the declared receiver image and reopen the complete source fibre.
    pub fn decode(
        &self,
        native: NativeStateId,
        receiver: ReceiverId,
    ) -> Result<DecodedReceiverImage, ReceiverHistoryRefusal> {
        let observation = self
            .receiver_factors
            .iter()
            .find(|factor| factor.native == native && factor.receiver == receiver)
            .map(|factor| factor.observation)
            .ok_or(ReceiverHistoryRefusal::UnknownReceiverFactor { native, receiver })?;
        let reconstruction_fibre = self
            .reconstruction_fibres
            .iter()
            .find(|fibre| fibre.native == native)
            .map(|fibre| fibre.sources.clone())
            .ok_or(ReceiverHistoryRefusal::UnknownNative(native))?;
        Ok(DecodedReceiverImage {
            native,
            receiver,
            observation,
            reconstruction_fibre,
        })
    }

    fn source_step(
        &self,
        source: ItemId,
        generator: InputId,
    ) -> Result<ItemId, ReceiverHistoryRefusal> {
        self.generators
            .iter()
            .find(|square| square.generator == generator)
            .ok_or(ReceiverHistoryRefusal::UnknownGenerator(generator))?
            .source
            .iter()
            .find(|edge| edge.from == source)
            .map(|edge| edge.to)
            .ok_or(ReceiverHistoryRefusal::UnknownSource(source))
    }

    pub fn native_step(
        &self,
        native: NativeStateId,
        generator: InputId,
    ) -> Result<NativeStateId, ReceiverHistoryRefusal> {
        self.generators
            .iter()
            .find(|square| square.generator == generator)
            .ok_or(ReceiverHistoryRefusal::UnknownGenerator(generator))?
            .native
            .iter()
            .find(|edge| edge.from == native)
            .map(|edge| edge.to)
            .ok_or(ReceiverHistoryRefusal::UnknownNative(native))
    }

    /// Derive the ordered-word square by composing the already-checked generator squares.
    pub fn ordered_word_consequence(
        &self,
        source_start: ItemId,
        word: &[InputId],
    ) -> Result<OrderedWordConsequence, ReceiverHistoryRefusal> {
        let native_start = self.encode(source_start)?;
        let mut source_end = source_start;
        let mut native_end = native_start;
        for generator in word {
            source_end = self.source_step(source_end, *generator)?;
            native_end = self.native_step(native_end, *generator)?;
        }
        let encoded_source_end = self.encode(source_end)?;
        Ok(OrderedWordConsequence {
            source_start,
            native_start,
            word: word.to_vec(),
            source_end,
            encoded_source_end,
            native_end,
        })
    }

    /// Conduct an arbitrary ordered word natively and decode its declared endpoint image.
    pub fn decode_after_word(
        &self,
        native_start: NativeStateId,
        word: &[InputId],
        receiver: ReceiverId,
    ) -> Result<DecodedReceiverImage, ReceiverHistoryRefusal> {
        let mut native = native_start;
        for generator in word {
            native = self.native_step(native, *generator)?;
        }
        self.decode(native, receiver)
    }
}

impl PartialReceiverHistoryCompression {
    pub fn read(bytes: &[u8]) -> Result<Self, ReceiverHistoryRefusal> {
        let compression: Self = serde_json::from_slice(bytes)
            .map_err(|error| ReceiverHistoryRefusal::Wire(error.to_string()))?;
        compression.validate()?;
        Ok(compression)
    }

    /// Reopen the partial action and check every source/native incidence and terminus.
    pub fn validate(&self) -> Result<(), ReceiverHistoryRefusal> {
        if self.schema != "holonic-engine.partial-receiver-history-compression.v1" {
            return Err(ReceiverHistoryRefusal::Wire(format!(
                "unknown schema {}",
                self.schema
            )));
        }
        let source_set = self
            .source_population
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if source_set.is_empty() || source_set.len() != self.source_population.len() {
            return Err(ReceiverHistoryRefusal::SourcePopulation);
        }
        let native_set = self
            .native_population
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        if native_set.is_empty() || native_set.len() != self.native_population.len() {
            return Err(ReceiverHistoryRefusal::NativePopulation);
        }
        let mut encoded = BTreeMap::<ItemId, NativeStateId>::new();
        for assignment in &self.quotient {
            if !source_set.contains(&assignment.source)
                || !native_set.contains(&assignment.native)
                || encoded
                    .insert(assignment.source, assignment.native)
                    .is_some()
            {
                return Err(ReceiverHistoryRefusal::SourceOccursInPluralFibres(
                    assignment.source,
                ));
            }
        }
        if source_set
            .iter()
            .any(|source| !encoded.contains_key(source))
        {
            return Err(ReceiverHistoryRefusal::SourcePopulation);
        }
        let mut fibre_union = BTreeSet::new();
        let mut fibre_natives = BTreeSet::new();
        for fibre in &self.reconstruction_fibres {
            if fibre.sources.is_empty()
                || !native_set.contains(&fibre.native)
                || !fibre_natives.insert(fibre.native)
            {
                return Err(ReceiverHistoryRefusal::EmptyFibre(fibre.native));
            }
            for source in &fibre.sources {
                if !source_set.contains(source)
                    || !fibre_union.insert(*source)
                    || encoded.get(source) != Some(&fibre.native)
                {
                    return Err(ReceiverHistoryRefusal::SourceOccursInPluralFibres(*source));
                }
            }
        }
        if fibre_union != source_set || fibre_natives != native_set {
            return Err(ReceiverHistoryRefusal::NativePopulation);
        }

        let receiver_set = self
            .receiver_factors
            .iter()
            .map(|factor| factor.receiver)
            .collect::<BTreeSet<_>>();
        let factor_keys = self
            .receiver_factors
            .iter()
            .map(|factor| (factor.native, factor.receiver))
            .collect::<BTreeSet<_>>();
        if receiver_set.is_empty()
            || factor_keys.len() != self.receiver_factors.len()
            || native_set.iter().any(|native| {
                receiver_set
                    .iter()
                    .any(|receiver| !factor_keys.contains(&(*native, *receiver)))
            })
        {
            return Err(ReceiverHistoryRefusal::NativePopulation);
        }

        let mut generator_ids = BTreeSet::new();
        let mut native_transport_entries = 0u64;
        for square in &self.generators {
            if !generator_ids.insert(square.generator) {
                return Err(ReceiverHistoryRefusal::DuplicateGenerator(square.generator));
            }
            let source_map = square
                .source
                .iter()
                .map(|edge| (edge.from, edge.to))
                .collect::<BTreeMap<_, _>>();
            if source_map.len() != square.source.len()
                || source_map
                    .iter()
                    .any(|(from, to)| !source_set.contains(from) || !source_set.contains(to))
                || !source_map
                    .keys()
                    .copied()
                    .collect::<BTreeSet<_>>()
                    .is_disjoint(&square.terminating_sources)
                || source_map
                    .keys()
                    .copied()
                    .chain(square.terminating_sources.iter().copied())
                    .collect::<BTreeSet<_>>()
                    != source_set
            {
                return Err(ReceiverHistoryRefusal::SourcePopulation);
            }
            let native_map = square
                .native
                .iter()
                .map(|edge| (edge.from, edge.to))
                .collect::<BTreeMap<_, _>>();
            native_transport_entries += native_map.len() as u64;
            if native_map.len() != square.native.len()
                || native_map
                    .iter()
                    .any(|(from, to)| !native_set.contains(from) || !native_set.contains(to))
                || !native_map
                    .keys()
                    .copied()
                    .collect::<BTreeSet<_>>()
                    .is_disjoint(&square.terminating_natives)
                || native_map
                    .keys()
                    .copied()
                    .chain(square.terminating_natives.iter().copied())
                    .collect::<BTreeSet<_>>()
                    != native_set
            {
                return Err(ReceiverHistoryRefusal::NativePopulation);
            }
            for source in &source_set {
                let native = encoded[source];
                match source_map.get(source) {
                    Some(target) => {
                        if native_map.get(&native) != Some(&encoded[target]) {
                            return Err(ReceiverHistoryRefusal::GeneratorSquareDoesNotCommute {
                                generator: square.generator,
                                source_item: *source,
                            });
                        }
                    }
                    None => {
                        if !square.terminating_sources.contains(source)
                            || !square.terminating_natives.contains(&native)
                        {
                            return Err(ReceiverHistoryRefusal::GeneratorDoesNotDescend {
                                generator: square.generator,
                                native,
                            });
                        }
                    }
                }
            }
        }
        for separator in &self.first_separators {
            if separator.left == separator.right
                || !source_set.contains(&separator.left)
                || !source_set.contains(&separator.right)
                || separator.distinguishing_word.is_empty()
                || separator
                    .distinguishing_word
                    .iter()
                    .any(|generator| !generator_ids.contains(generator))
                || separator.witness.is_some_and(|(receiver, left, right)| {
                    !receiver_set.contains(&receiver) || left == right
                })
                || (!separator.separated_by_terminus && separator.witness.is_none())
            {
                return Err(ReceiverHistoryRefusal::Separator);
            }
        }
        let expected = ReceiverHistoryWork {
            quotient_assignments: source_set.len() as u64,
            receiver_factor_reads: (source_set.len() * receiver_set.len()) as u64,
            source_transport_reads: (source_set.len() * self.generators.len()) as u64,
            native_transport_entries,
            generator_square_checks: (source_set.len() * self.generators.len()) as u64,
        };
        if self.construction_work != expected {
            return Err(ReceiverHistoryRefusal::ConstructionWork);
        }
        Ok(())
    }

    /// Found the exact partial native action from a stable receiver/history partition.
    pub fn found(
        system: &dyn ObservedSystem,
        exact: &ReceiverExactCompression,
    ) -> Result<Self, ReceiverHistoryRefusal> {
        let mut source_population = system.items();
        source_population.sort_unstable();
        source_population.dedup();
        let source_set = source_population.iter().copied().collect::<BTreeSet<_>>();
        let mut quotient = Vec::with_capacity(source_population.len());
        let mut reconstruction_fibres = Vec::with_capacity(exact.conduct.blocks.len());
        let mut encoded = BTreeMap::<ItemId, NativeStateId>::new();
        for (at, sources) in exact.conduct.blocks.iter().enumerate() {
            let native = NativeStateId(at as u64);
            if sources.is_empty() {
                return Err(ReceiverHistoryRefusal::EmptyFibre(native));
            }
            for source in sources {
                if encoded.insert(*source, native).is_some() {
                    return Err(ReceiverHistoryRefusal::SourceOccursInPluralFibres(*source));
                }
                quotient.push(QuotientAssignment {
                    source: *source,
                    native,
                });
            }
            reconstruction_fibres.push(ReconstructionFibre {
                native,
                sources: sources.clone(),
            });
        }
        if source_population
            .iter()
            .any(|source| !encoded.contains_key(source))
        {
            return Err(ReceiverHistoryRefusal::SourcePopulation);
        }
        quotient.sort_by_key(|assignment| assignment.source);
        let native_population = reconstruction_fibres
            .iter()
            .map(|fibre| fibre.native)
            .collect::<Vec<_>>();

        let receivers = system.receivers();
        let mut receiver_factors = Vec::new();
        let mut receiver_factor_reads = 0u64;
        for fibre in &reconstruction_fibres {
            for receiver in &receivers {
                let mut readings = fibre.sources.iter().map(|source| {
                    receiver_factor_reads += 1;
                    system.observation(*source, *receiver)
                });
                let first = readings
                    .next()
                    .ok_or(ReceiverHistoryRefusal::EmptyFibre(fibre.native))?;
                if readings.any(|reading| reading != first) {
                    return Err(ReceiverHistoryRefusal::ReceiverDoesNotFactor {
                        native: fibre.native,
                        receiver: *receiver,
                    });
                }
                receiver_factors.push(ReceiverFactor {
                    native: fibre.native,
                    receiver: *receiver,
                    observation: first,
                });
            }
        }

        let mut generators = Vec::new();
        let mut source_transport_reads = 0u64;
        let mut native_transport_entries = 0u64;
        let mut generator_square_checks = 0u64;
        for generator in system.inputs() {
            let mut source = Vec::new();
            let mut terminating_sources = BTreeSet::new();
            for from in &source_population {
                source_transport_reads += 1;
                match system.successor(*from, generator) {
                    Some(to) if source_set.contains(&to) => {
                        source.push(SourceTransport { from: *from, to });
                    }
                    Some(to) => {
                        return Err(ReceiverHistoryRefusal::SourceTransportLeavesPopulation {
                            generator,
                            source_item: *from,
                            target: to,
                        });
                    }
                    None => {
                        terminating_sources.insert(*from);
                    }
                }
            }
            let source_map = source
                .iter()
                .map(|edge| (edge.from, edge.to))
                .collect::<BTreeMap<_, _>>();
            let mut native = Vec::new();
            let mut terminating_natives = BTreeSet::new();
            for fibre in &reconstruction_fibres {
                let continuing = fibre
                    .sources
                    .iter()
                    .filter_map(|member| source_map.get(member))
                    .map(|target| encoded[target])
                    .collect::<BTreeSet<_>>();
                let terminating = fibre
                    .sources
                    .iter()
                    .filter(|member| terminating_sources.contains(member))
                    .count();
                if terminating == fibre.sources.len() {
                    terminating_natives.insert(fibre.native);
                } else if terminating == 0 && continuing.len() == 1 {
                    native_transport_entries += 1;
                    native.push(NativeTransport {
                        from: fibre.native,
                        to: *continuing
                            .iter()
                            .next()
                            .expect("one target was established"),
                    });
                } else {
                    return Err(ReceiverHistoryRefusal::GeneratorDoesNotDescend {
                        generator,
                        native: fibre.native,
                    });
                }
            }
            let native_map = native
                .iter()
                .map(|edge| (edge.from, edge.to))
                .collect::<BTreeMap<_, _>>();
            for from in &source_population {
                generator_square_checks += 1;
                match source_map.get(from) {
                    Some(to) if native_map.get(&encoded[from]) == Some(&encoded[to]) => {}
                    None if terminating_natives.contains(&encoded[from]) => {}
                    _ => {
                        return Err(ReceiverHistoryRefusal::GeneratorSquareDoesNotCommute {
                            generator,
                            source_item: *from,
                        });
                    }
                }
            }
            generators.push(PartialGeneratorSquare {
                generator,
                source,
                terminating_sources,
                native,
                terminating_natives,
            });
        }
        let compression = Self {
            schema: "holonic-engine.partial-receiver-history-compression.v1".to_owned(),
            source_population,
            native_population,
            quotient,
            receiver_factors,
            generators,
            reconstruction_fibres,
            first_separators: exact.collapsed.clone(),
            construction_work: ReceiverHistoryWork {
                quotient_assignments: encoded.len() as u64,
                receiver_factor_reads,
                source_transport_reads,
                native_transport_entries,
                generator_square_checks,
            },
        };
        compression.validate()?;
        Ok(compression)
    }

    pub fn encode(&self, source: ItemId) -> Result<NativeStateId, ReceiverHistoryRefusal> {
        self.quotient
            .binary_search_by_key(&source, |assignment| assignment.source)
            .ok()
            .and_then(|at| self.quotient.get(at))
            .map(|assignment| assignment.native)
            .ok_or(ReceiverHistoryRefusal::UnknownSource(source))
    }
}
